"""Client addresses for rate limiting (docs/ratelimit.md, sections 6 and 7)."""

import ipaddress

_MAPPED = ipaddress.ip_network("::ffff:0:0/96")


def norm_addr(a):
    if a.version == 6 and a.ipv4_mapped is not None:
        return a.ipv4_mapped
    return a


def norm_net(n):
    if n.version == 6 and n.prefixlen >= 96 and n.subnet_of(_MAPPED):
        return ipaddress.ip_network(
            (ipaddress.IPv4Address(int(n.network_address) & 0xFFFFFFFF), n.prefixlen - 96))
    return n


def parse_addr(text):
    """An address entry (7.3) as an address object, or None."""
    if not isinstance(text, str) or not text.isascii():
        return None
    s = text
    if s.startswith("["):
        end = s.find("]")
        if end < 0:
            return None
        rest = s[end + 1:]
        s = s[1:end]
        if rest:
            if not rest.startswith(":") or not _port(rest[1:]):
                return None
        try:
            return norm_addr(ipaddress.IPv6Address(s))
        except ValueError:
            return None
    if s.count(":") == 1:
        host, port = s.split(":")
        if not _port(port):
            return None
        s = host
        try:
            return ipaddress.IPv4Address(s)
        except ValueError:
            return None
    if "%" in s:
        return None
    try:
        return norm_addr(ipaddress.ip_address(s))
    except ValueError:
        return None


def _port(p):
    return p.isdigit() and p.isascii() and int(p) <= 65535


def in_any(addr, nets) -> bool:
    return any(addr.version == n.version and addr in n for n in nets)


def client_address(request, trusted):
    """The client address (section 7); an address object, or the raw peer text when unparsable."""
    peer = parse_addr(request.peer)
    if peer is None:
        return request.peer
    if not in_any(peer, trusted):
        return peer
    entries = []
    for v in request.headers.get_all("X-Forwarded-For"):
        entries.extend(e.strip(" \t") for e in v.split(","))
    if not entries:
        return peer
    prev = peer
    for e in reversed(entries):
        a = parse_addr(e)
        if a is None:
            return prev
        if not in_any(a, trusted):
            return a
        prev = a
    return parse_addr(entries[0])


def key_text(addr) -> str:
    if isinstance(addr, str):
        return addr
    if addr.version == 4:
        return str(addr)
    return str(ipaddress.ip_network((addr, 64), strict=False))
