"""Stage 3: rate limiting (docs/ratelimit.md)."""

import math
from fractions import Fraction

from frontdoor.ratelimit.addr import client_address, in_any, key_text
from frontdoor.ratelimit.state import new_state

NAME = "ratelimit"
INF = float("inf")


class State:
    def __init__(self, config):
        self.limits = config.section("limit", None) or []
        self.trusted = config.section("clients", None) or ()
        self.buckets = {lim.name: {} for lim in self.limits}
        self.refused = {lim.name: 0 for lim in self.limits}
        self.clock = None


def setup(config):
    return State(config)


def _key(lim, ctx, client):
    vals = []
    for part in lim.key:
        if part == "tenant":
            v = ctx.tenant
        elif part == "client":
            v = key_text(client)
        elif part == "route":
            v = ctx.route.name
        elif part == "method":
            v = ctx.request.method.upper()
        else:
            v = ctx.request.headers.get(part[len("header:"):])
            if v is not None:
                v = v.strip(" \t")
        if v is None or v == "":
            return None
        vals.append(v)
    return tuple(vals)


def handle(ctx, st):
    if not st.limits:
        return None
    req = ctx.request
    method = req.method.upper()
    client = client_address(req, st.trusted)
    covering = []
    for lim in st.limits:
        if lim.routes is not None and ctx.route.name not in lim.routes:
            continue
        if lim.methods is not None and method not in lim.methods:
            continue
        key = _key(lim, ctx, client)
        if key is None:
            continue
        if not isinstance(client, str) or True:
            if not isinstance(client, str) and in_any(client, lim.exempt):
                continue
        covering.append((lim, key))
    if not covering:
        return None
    now = req.ts_ms if st.clock is None else max(st.clock, req.ts_ms)
    st.clock = now
    checked = []
    for lim, key in covering:
        d = st.buckets[lim.name]
        s = d.get(key)
        if s is None:
            s = d[key] = new_state(lim, now)
        else:
            s.refill(now)
        c = lim.cost_of(method)
        checked.append((lim, s, c, c <= lim.capacity and s.allows(c)))
    refusing = [t for t in checked if not t[3]]
    if not refusing:
        for lim, s, c, _ in checked:
            s.charge(c)
        best = None
        for lim, s, c, _ in checked:
            r = s.remaining()
            if best is None or r < best[0]:
                best = (r, lim, s)
        _, lim, s = best
        _headers(ctx, lim, s, now)
        return None
    best = None
    for lim, s, c, _ in refusing:
        st.refused[lim.name] += 1
        w = INF if c > lim.capacity else s.wait(c, now)
        if best is None or w > best[0]:
            best = (w, lim, s)
    w, lim, s = best
    _headers(ctx, lim, s, now)
    if w != INF:
        ctx.headers["Retry-After"] = str(max(1, math.ceil(Fraction(w) / 1000)))
    return 429


def _headers(ctx, lim, s, now):
    ctx.headers["RateLimit-Limit"] = str(lim.capacity)
    ctx.headers["RateLimit-Remaining"] = str(s.remaining())
    ctx.headers["RateLimit-Reset"] = str(s.reset(now))


def summary(st):
    if not st.limits:
        return {}
    return {"limited": dict(st.refused)}
